When using the  `typeOf` keyword, type definitions of all functions will now have a "parameters" field containing a list of the type definitions of all function parameters.

This is very useful for fully automated runtime type checking in RPC architectures.

### Example:

Code:
(Note the use of various function syntaxes)

```
function sum(a: number, b: number) {
  return a + b;
}

function prod(a: number, b: number) {
  return a + b;
}

const length = (s: string) => s.length;

const extractAttribute = (obj: object, attribute: string) => obj[attribute];

class Arrays {
  static get(array: number[], index: number) {
    return array[index];
  }
}

export const API = {
  numbers: {
    sum,
    prod
  },
  objects: {
    length,
    extractAttribute,
    extractArrayEl: Arrays.get
  }
};
```

Produced schema:
(note the parameters lists)

```
{
  "type": "object",
  "properties": {
    "api": {
      "type": "object",
      "properties": {
        "numbers": {
          "type": "object",
          "properties": {
            "sum": {
              "typeof": "function",
              "parameters": [
                {
                  "type": "number"
                },
                {
                  "type": "number"
                }
              ]
            },
            "prod": {
              "typeof": "function",
              "parameters": [
                {
                  "type": "number"
                },
                {
                  "type": "number"
                }
              ]
            }
          }
        },
        "objects": {
          "type": "object",
          "properties": {
            "length": {
              "typeof": "function",
              "parameters": [
                {
                  "type": "string"
                }
              ]
            },
            "extractAttribute": {
              "typeof": "function",
              "parameters": [
                {
                  "type": "object",
                  "properties": {},
                  "additionalProperties": true
                },
                {
                  "type": "string"
                }
              ]
            },
            "extractArrayEl": {
              "typeof": "function",
              "parameters": [
                {
                  "type": "array",
                  "items": {
                    "type": "number"
                  }
                },
                {
                  "type": "number"
                }
              ]
            }
          }
        }
      }
    }
  },
  "$schema": "http://json-schema.org/draft-07/schema#"
}
```

Now, that all the ADC stuff for the B-G431B-ESC1 board is in hardware specific files anyway, I see no value in not supporting the additional ADC channels for the bus voltage, temp sensor and poti. The code for these was proposed long time ago already by @HoeckDK on the SimpleFOC community forum. To read e.g. the temp sensor of the board, apply this PR and the call 

float Temp = _readADCVoltageInline(A_TEMPERATURE, currentSense.params);

It would be cool if this PR was accepted, this would safe me quite some time to apply it to all new versions over and over again...

I tested the empty struct and it worked.
Code i used to test the code.
```go
package main

import (
	"fmt"
	jsone "github.com/clarketm/json"
)
type Test struct {
	Hello string `json:"hello,omitempty"`
	User  User   `json:"user,omitempty"`
}
type User struct {
	Str string `json:"str,omitempty"`
}
func main() {
	var TestStr = Test{ User: User{ Str: ""}}
	b, err := jsone.Marshal(TestStr) 
	if err != nil {
		panic(err)
	}
	var mapSt map[string]any
	if ers := jsone.Unmarshal(b, &mapSt); ers !=nil {
		panic(ers)
	}
	fmt.Println(mapSt)
}
```

